#!/usr/bin/env python3
import os
import re
import json
from datetime import datetime

SESSION_ID = "f7310655-af2f-42b0-a6f1-c19832a8827d"
WORKSPACE_DIR = "~/d/hackathon-builder-cup-manufacturing-anomaly"
TRANSCRIPT_PATH = f"~/.gemini/antigravity-cli/brain/{SESSION_ID}/.system_generated/logs/transcript_full.jsonl"
EXPORT_DIR = os.path.join(WORKSPACE_DIR, ".sessions")
USER_HOME = os.path.expanduser("~")

os.makedirs(EXPORT_DIR, exist_ok=True)

now = datetime.now()
iso_now = now.astimezone().isoformat()

json_filename = f"session-{SESSION_ID}.json"
json_path = os.path.join(EXPORT_DIR, json_filename)

def sanitize_text(text):
    if not isinstance(text, str):
        return text
    # 1. API Keys & Tokens
    text = re.sub(r'\b(sk-[a-zA-Z0-9_\-]{20,})\b', '[REDACTED_API_KEY]', text)
    text = re.sub(r'\b(AIza[a-zA-Z0-9_\-]{35})\b', '[REDACTED_GEMINI_KEY]', text)
    text = re.sub(r'\b(ghp_[a-zA-Z0-9]{36}|gho_[a-zA-Z0-9]{36}|github_pat_[a-zA-Z0-9_]{82})\b', '[REDACTED_GITHUB_TOKEN]', text)
    text = re.sub(r'\b(glpat-[a-zA-Z0-9\-]{20,})\b', '[REDACTED_GITLAB_TOKEN]', text)
    text = re.sub(r'\b(AKIA[0-9A-Z]{16})\b', '[REDACTED_AWS_KEY]', text)
    text = re.sub(r'\b(eyJ[a-zA-Z0-9_-]{10,}\.eyJ[a-zA-Z0-9_-]{10,}\.[a-zA-Z0-9_-]+)\b', '[REDACTED_JWT]', text)
    # 2. Private Keys
    text = re.sub(r'-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----', '[REDACTED_PRIVATE_KEY]', text)
    # 3. DB & Auth Connection Strings
    text = re.sub(r'(?:postgres|postgresql|mongodb(?:\+srv)?|mysql|redis):\/\/[^\s"\'`]+', '[REDACTED_DB_URL]', text)
    # 4. Env passwords and secrets
    text = re.sub(r'(?i)\b((?:PASSWORD|SECRET|API_KEY|TOKEN|AUTH|BEARER)\s*[:=]\s*["\'`]?)([^"\'`\s\n\r]+)(["\'`]?)', r'\1[REDACTED]\3', text)
    # 5. Local path normalization
    text = text.replace(USER_HOME, "~")
    return text

def sanitize_obj(obj):
    if isinstance(obj, str):
        return sanitize_text(obj)
    elif isinstance(obj, dict):
        return {k: sanitize_obj(v) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [sanitize_obj(v) for v in obj]
    return obj

with open(TRANSCRIPT_PATH, "r", encoding="utf-8") as f:
    steps = [json.loads(line) for line in f]

history = []
commands_run = []
files_created = [
    f".sessions/{json_filename}"
]
files_modified = []

for step in steps:
    source = step.get("source")
    step_type = step.get("type")
    created_at = step.get("created_at")

    if step_type == "USER_INPUT":
        raw_content = step.get("content", "")
        m = re.search(r'<USER_REQUEST>\s*(.*?)\s*</USER_REQUEST>', raw_content, re.DOTALL)
        user_text = m.group(1).strip() if m else raw_content.strip()
        history.append({
            "turn": len(history) + 1,
            "role": "user",
            "timestamp": created_at,
            "content": sanitize_text(user_text)
        })
    elif step_type in ("PLANNER_RESPONSE", "GENERIC"):
        tool_calls = step.get("tool_calls", [])
        content = step.get("content", "")

        for tc in tool_calls:
            name = tc.get("name")
            args = tc.get("args", {})
            if name == "run_command":
                cmd = args.get("CommandLine", "")
                if cmd:
                    commands_run.append(sanitize_text(cmd))
            elif name == "write_to_file":
                target = args.get("TargetFile", "")
                if target:
                    normalized = sanitize_text(target)
                    if normalized not in files_created:
                        files_created.append(normalized)
            elif name == "replace_file_content":
                target = args.get("TargetFile", "")
                if target:
                    normalized = sanitize_text(target)
                    if normalized not in files_modified:
                        files_modified.append(normalized)

        if tool_calls or (content and source == "MODEL" and step_type == "PLANNER_RESPONSE"):
            if not history or history[-1]["role"] != "assistant":
                history.append({
                    "turn": len(history) + 1,
                    "role": "assistant",
                    "timestamp": created_at,
                    "tool_calls": [],
                    "content": ""
                })
            asst = history[-1]
            for tc in tool_calls:
                asst["tool_calls"].append({
                    "tool": tc.get("name"),
                    "args": sanitize_obj(tc.get("args")),
                    "status": "success"
                })
            if content:
                clean_content = sanitize_text(content.strip())
                if asst["content"]:
                    asst["content"] += "\n\n" + clean_content
                else:
                    asst["content"] = clean_content

if history and history[-1]["role"] == "assistant" and not history[-1]["content"]:
    history[-1]["content"] = f"Exported local Antigravity session into structured JSON (`.sessions/{json_filename}`)."

export_json_data = {
    "session_id": SESSION_ID,
    "exported_at": iso_now,
    "runtime": "Antigravity",
    "summary": {
        "total_turns": len(history),
        "files_created": files_created,
        "files_modified": files_modified,
        "commands_run": commands_run
    },
    "history": history
}

with open(json_path, "w", encoding="utf-8") as f:
    json.dump(export_json_data, f, indent=2, ensure_ascii=False)

# Remove any non-matching session files in .sessions
for f_item in os.listdir(EXPORT_DIR):
    if f_item != json_filename:
        try:
            os.remove(os.path.join(EXPORT_DIR, f_item))
        except:
            pass

print(f"SUCCESS: Exported to {json_path}")
